package com.example.deviceguard;
import android.os.Bundle;import android.text.InputType;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.deviceguard.models.*;import com.example.deviceguard.network.*;import com.example.deviceguard.utils.*;import java.util.*;import retrofit2.*;
public class MainActivity extends AppCompatActivity{
 private EditText name,email,password,server;private TextView title,subtitle,status;private Button primary,switchMode,testServer;private boolean registerMode=false;private SessionManager session;private ApiService api;
 @Override protected void onCreate(Bundle b){super.onCreate(b);session=new SessionManager(this);setContentView(R.layout.activity_main);bind();if(session.loggedIn()){goDashboard();return;}showAuth();}
 private void bind(){title=findViewById(R.id.title);subtitle=findViewById(R.id.subtitle);name=findViewById(R.id.name);email=findViewById(R.id.email);password=findViewById(R.id.password);server=findViewById(R.id.server);status=findViewById(R.id.status);primary=findViewById(R.id.primary);switchMode=findViewById(R.id.switchMode);testServer=findViewById(R.id.testServer);server.setText(session.getServerUrl());
  primary.setOnClickListener(v->submit());switchMode.setOnClickListener(v->{registerMode=!registerMode;showAuth();});testServer.setOnClickListener(v->testServer()); }
 private void showAuth(){title.setText(registerMode?"Create your DeviceGuard account":"Welcome to DeviceGuard");subtitle.setText(registerMode?"Use this account to manage authorized devices.":"Securely connect, pair and locate your devices.");name.setVisibility(registerMode?View.VISIBLE:View.GONE);primary.setText(registerMode?"Create account":"Login");switchMode.setText(registerMode?"Already have an account? Login":"New here? Create an account");status.setText("");}
 private boolean saveServer(){String u=server.getText().toString().trim();if(u.isEmpty()){status.setText("Enter the backend URL first.");return false;}session.setServerUrl(u);RetrofitClient.reset();api=RetrofitClient.get(this);return true;}
 private void testServer(){if(!saveServer())return;api.health().enqueue(new Callback<MessageResponse>(){public void onResponse(Call<MessageResponse>c,Response<MessageResponse>r){status.setText(r.isSuccessful()?"✓ Backend reachable":"Backend error: "+ApiError.message(r));}public void onFailure(Call<MessageResponse>c,Throwable t){status.setText("Cannot reach backend: "+t.getMessage());}});}
 private void submit(){if(!saveServer())return;Map<String,String>x=new HashMap<>();x.put("email",email.getText().toString().trim());x.put("password",password.getText().toString());if(registerMode)x.put("name",name.getText().toString().trim());Call<AuthResponse> call=registerMode?api.register(x):api.login(x);call.enqueue(new Callback<AuthResponse>(){public void onResponse(Call<AuthResponse>c,Response<AuthResponse>r){if(r.isSuccessful()&&r.body()!=null){session.save(r.body().token,r.body().user.id);goDashboard();}else status.setText(ApiError.message(r));}public void onFailure(Call<AuthResponse>c,Throwable t){status.setText("Network error: "+t.getMessage());}});}
 private void goDashboard(){startActivity(new android.content.Intent(this,DashboardActivity.class));finish();}
}
